using MongoDB.Driver; using SmartSolarMicrogrid.Api.Data; using SmartSolarMicrogrid.Api.DTOs; using SmartSolarMicrogrid.Api.Models;
namespace SmartSolarMicrogrid.Api.Services;
public interface IStationService { Task<List<SolarStationInfo>> GetAsync(bool activeOnly=true); Task<SolarStationInfo> CreateAsync(StationRequest r); Task<SolarStationInfo> UpdateAsync(string id,StationRequest r); Task DeactivateAsync(string id); }
public sealed class StationService(MongoContext db) : IStationService { public Task<List<SolarStationInfo>>GetAsync(bool a=true)=>db.Stations.Find(x=>!a||x.IsActive).ToListAsync();public async Task<SolarStationInfo>CreateAsync(StationRequest r){var s=new SolarStationInfo{Name=r.Name,Location=r.Location,Latitude=r.Latitude,Longitude=r.Longitude,CapacityKwh=r.CapacityKwh,BatteryStorageSlots=r.BatteryStorageSlots};await db.Stations.InsertOneAsync(s);return s;}public async Task<SolarStationInfo>UpdateAsync(string id,StationRequest r){var s=await db.Stations.Find(x=>x.Id==id).FirstOrDefaultAsync()??throw new KeyNotFoundException("Station not found.");s.Name=r.Name;s.Location=r.Location;s.Latitude=r.Latitude;s.Longitude=r.Longitude;s.CapacityKwh=r.CapacityKwh;s.BatteryStorageSlots=r.BatteryStorageSlots;s.UpdatedAt=DateTime.UtcNow;await db.Stations.ReplaceOneAsync(x=>x.Id==id,s);return s;}public async Task DeactivateAsync(string id){if(await db.Reservations.Find(x=>x.StationId==id&&(x.Status==ReservationStatus.Pending||x.Status==ReservationStatus.Confirmed)).AnyAsync())throw new InvalidOperationException("Station has active reservations.");var s=await db.Stations.Find(x=>x.Id==id).FirstOrDefaultAsync()??throw new KeyNotFoundException("Station not found.");s.IsActive=false;await db.Stations.ReplaceOneAsync(x=>x.Id==id,s);} }
public interface ISlotService { Task<List<EnergyBookingSlot>> GetAsync(string? stationId); Task<EnergyBookingSlot> CreateAsync(SlotRequest r); Task<EnergyBookingSlot> UpdateAsync(string id,SlotRequest r); Task DeleteAsync(string id); }
public sealed class SlotService(MongoContext db) : ISlotService { public Task<List<EnergyBookingSlot>>GetAsync(string? id)=>db.Slots.Find(x=>x.IsActive&&(id==null||x.StationId==id)&&x.EndTime>DateTime.UtcNow).ToListAsync();public async Task<EnergyBookingSlot>CreateAsync(SlotRequest r){if(r.EndTime<=r.StartTime)throw new InvalidOperationException("End time must be after start time.");if(await db.Stations.Find(x=>x.Id==r.StationId&&x.IsActive).FirstOrDefaultAsync()==null)throw new InvalidOperationException("Active station not found.");var s=new EnergyBookingSlot{StationId=r.StationId,StartTime=r.StartTime.ToUniversalTime(),EndTime=r.EndTime.ToUniversalTime(),AvailableKwh=r.AvailableKwh,PricePerKwh=r.PricePerKwh};await db.Slots.InsertOneAsync(s);return s;}public async Task<EnergyBookingSlot>UpdateAsync(string id,SlotRequest r){var s=await db.Slots.Find(x=>x.Id==id).FirstOrDefaultAsync()??throw new KeyNotFoundException("Slot not found.");if(r.EndTime<=r.StartTime)throw new InvalidOperationException("End time must be after start time.");s.StartTime=r.StartTime.ToUniversalTime();s.EndTime=r.EndTime.ToUniversalTime();s.AvailableKwh=r.AvailableKwh;s.PricePerKwh=r.PricePerKwh;s.UpdatedAt=DateTime.UtcNow;await db.Slots.ReplaceOneAsync(x=>x.Id==id,s);return s;}public async Task DeleteAsync(string id){if(await db.Reservations.Find(x=>x.SlotId==id&&(x.Status==ReservationStatus.Pending||x.Status==ReservationStatus.Confirmed)).AnyAsync())throw new InvalidOperationException("Slot has active reservations.");if((await db.Slots.DeleteOneAsync(x=>x.Id==id)).DeletedCount==0)throw new KeyNotFoundException("Slot not found.");} }
